<?php
$start=(string)get('start',date('Y-m-01'));$end=(string)get('end',date('Y-m-d'));
$summary=db()->query("SELECT COUNT(*) total, SUM(status='selesai') selesai, SUM(status='menunggu') menunggu, SUM(status='ditolak') ditolak FROM pengajuan")->fetch();
$warga=(int)db()->query("SELECT COUNT(*) FROM data_warga WHERE status='aktif'")->fetchColumn();$events=(int)db()->query("SELECT COUNT(*) FROM kegiatan WHERE status<>'dibatalkan'")->fetchColumn();$complaints=db()->query("SELECT COUNT(*) total,SUM(status='selesai') selesai FROM keluhan_saran")->fetch();
$byService=db()->query('SELECT nama_layanan,COUNT(*) jumlah FROM pengajuan GROUP BY nama_layanan ORDER BY jumlah DESC LIMIT 6')->fetchAll();
$max=max(array_column($byService,'jumlah')?:[1]);
?>
<div class="page-heading"><div><h1>Laporan Administrasi</h1><p>Ringkasan statistik kependudukan, pelayanan, kegiatan, dan aspirasi.</p></div></div>
<div class="row g-3 mb-4"><div class="col-6 col-xl-3"><div class="stat-card"><div class="stat-icon"><i class="bi bi-people"></i></div><div class="stat-label">Warga Aktif</div><div class="stat-value"><?= number_format($warga) ?></div></div></div><div class="col-6 col-xl-3"><div class="stat-card"><div class="stat-icon"><i class="bi bi-file-earmark-text"></i></div><div class="stat-label">Total Pengajuan</div><div class="stat-value"><?= number_format((int)$summary['total']) ?></div><div class="stat-note"><?= (int)$summary['selesai'] ?> selesai</div></div></div><div class="col-6 col-xl-3"><div class="stat-card"><div class="stat-icon"><i class="bi bi-calendar-event"></i></div><div class="stat-label">Total Kegiatan</div><div class="stat-value"><?= number_format($events) ?></div></div></div><div class="col-6 col-xl-3"><div class="stat-card"><div class="stat-icon"><i class="bi bi-chat-square-text"></i></div><div class="stat-label">Keluhan & Saran</div><div class="stat-value"><?= number_format((int)$complaints['total']) ?></div><div class="stat-note"><?= (int)$complaints['selesai'] ?> selesai</div></div></div></div>
<div class="row g-4"><div class="col-xl-7"><section class="panel-card"><div class="panel-card-header"><h2 class="panel-title">Rekap Jenis Layanan</h2></div><div class="panel-card-body"><?php if(!$byService): ?><div class="empty-state"><strong>Belum ada data pengajuan</strong></div><?php else: foreach($byService as $s): ?><div class="mb-4"><div class="d-flex justify-content-between gap-3 mb-2"><strong class="fs-6"><?= e($s['nama_layanan']) ?></strong><span class="text-muted-2"><?= (int)$s['jumlah'] ?> pengajuan</span></div><div class="progress"><div class="progress-bar" style="width:<?= round(((int)$s['jumlah']/$max)*100) ?>%"></div></div></div><?php endforeach; endif; ?></div></section></div><div class="col-xl-5"><section class="panel-card"><div class="panel-card-header"><h2 class="panel-title">Status Pengajuan</h2></div><div class="panel-card-body"><?php foreach(['menunggu'=>'Menunggu','diproses'=>'Diproses','disetujui'=>'Disetujui','ditolak'=>'Ditolak','selesai'=>'Selesai'] as $key=>$label): ?><div class="d-flex justify-content-between align-items-center py-2 border-bottom"><span><?= e($label) ?></span><strong><?= (int)db()->query("SELECT COUNT(*) FROM pengajuan WHERE status=".db()->quote($key))->fetchColumn() ?></strong></div><?php endforeach; ?><div class="alert alert-info mt-3 mb-0">Statistik dihitung langsung dari data yang tersimpan dalam database.</div></div></section></div></div>
<section class="panel-card mt-4"><div class="panel-card-header"><h2 class="panel-title">Ekspor Data</h2></div><div class="panel-card-body"><p class="text-muted-2">Unduh laporan dalam format CSV yang dapat dibuka menggunakan Excel atau aplikasi spreadsheet lainnya.</p><form method="get" action="index.php" class="row g-3 align-items-end"><input type="hidden" name="action" value="export_report"><div class="col-md-3"><label class="form-label">Jenis laporan</label><select class="form-select" name="type"><option value="pengajuan">Pengajuan Administrasi</option><option value="warga">Data Warga</option><option value="keluhan">Keluhan & Saran</option></select></div><div class="col-md-3"><label class="form-label">Tanggal mulai</label><input class="form-control" type="date" name="start" value="<?= e($start) ?>"></div><div class="col-md-3"><label class="form-label">Tanggal selesai</label><input class="form-control" type="date" name="end" value="<?= e($end) ?>"></div><div class="col-md-3"><button class="btn btn-army w-100"><i class="bi bi-filetype-csv me-2"></i>Unduh CSV</button></div></form></div></section>
